From 095018911ba240a45831cd3cfb3b2e854df49c81 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 31 Oct 2026 22:26:26 +0100
Subject: [PATCH] applets/taskmanager: Highlight the last used window in the
 textual list

The textual list for grouped tasks only looked for the active window, so
it highlighted its top entry whenever another app was active. Highlight
the window activated most recently instead, the active one if any.

BUG: 486309
---
 applets/taskmanager/qml/GroupDialog.qml | 19 ++++++++++++-------
 1 file changed, 12 insertions(+), 7 deletions(-)

diff --git a/applets/taskmanager/qml/GroupDialog.qml b/applets/taskmanager/qml/GroupDialog.qml
index 8866a24ed9..f50cec4842 100644
--- a/applets/taskmanager/qml/GroupDialog.qml
+++ b/applets/taskmanager/qml/GroupDialog.qml
@@ -13,6 +13,7 @@ import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.kirigami as Kirigami
 import org.kde.plasma.plasmoid
+import org.kde.taskmanager as TaskManager
 import plasma.applet.org.kde.plasma.taskmanager as TaskManagerApplet

 PlasmaCore.PopupPlasmaWindow {
@@ -64,16 +65,20 @@ PlasmaCore.PopupPlasmaWindow {
     property /*PlasmaCore.ItemStatus*/int _oldAppletStatus: PlasmaCore.Types.UnknownStatus

     function findActiveTaskIndex(): void {
-        if (!tasksModel.activeTask) {
-            return;
-        }
+        // The active task, or else the one used last, has the latest activation time
+        let lastActivated = 0;
+        let index = -1;
         for (let i = 0; i < groupListView.count; i++) {
-            if (tasksModel.makeModelIndex((visualParent as Task).index, i) === tasksModel.activeTask) {
-                groupListView.positionViewAtIndex(i, ListView.Contain); // Prevent visual glitches
-                groupListView.currentIndex = i;
-                return;
+            const activated = tasksModel.data(tasksModel.makeModelIndex((visualParent as Task).index, i), TaskManager.AbstractTasksModel.LastActivated);
+            if (activated > lastActivated) {
+                lastActivated = activated;
+                index = i;
             }
         }
+        if (index >= 0) {
+            groupListView.positionViewAtIndex(index, ListView.Contain); // Prevent visual glitches
+            groupListView.currentIndex = index;
+        }
     }

     Component.onCompleted: {
